import{_ as e,o as t,c as r,Q as o}from"./chunks/framework.b67c47e6.js";const g=JSON.parse('{"title":"Properties in texts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/properties/index.md","filePath":"guide/properties/index.md","lastUpdated":1790016780000}'),d={name:"guide/properties/index.md"},a=o('<h1 id="properties-in-texts" tabindex="-1">Properties in texts <a class="header-anchor" href="#properties-in-texts" aria-label="Permalink to &quot;Properties in texts&quot;">​</a></h1><p>Several text fields in Produuz.it are <strong>templates</strong>: you type free text, and wherever you want a value from the model you write a property name between curly braces.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">Project: {project_name} - Phase: {phase_name}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">Project: {project_name} - Phase: {phase_name}</span></span></code></pre></div><p>becomes</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">Project: Zonnehof - Phase: Fase 2</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">Project: Zonnehof - Phase: Fase 2</span></span></code></pre></div><p>Every field that works this way has an <strong>Insert property</strong> button (<span style="font-family:monospace;">{ }</span>) on its right. It lists everything you can use in that field, including your own model properties, and inserts it where the cursor is. That button is the authoritative list — this page is the same list, written down.</p><nav class="table-of-contents"><ul><li><a href="#where-you-can-use-them">Where you can use them</a></li><li><a href="#panel-properties">Panel properties</a></li><li><a href="#part-properties">Part properties</a></li><li><a href="#your-own-properties">Your own properties</a></li><li><a href="#rules">Rules</a></li></ul></nav><h2 id="where-you-can-use-them" tabindex="-1">Where you can use them <a class="header-anchor" href="#where-you-can-use-them" aria-label="Permalink to &quot;Where you can use them&quot;">​</a></h2><table><thead><tr><th>Where</th><th>Field</th><th>Resolved per</th></tr></thead><tbody><tr><td>Company → Viewer settings</td><td><strong>Custom Viewer Header</strong></td><td>Panel</td></tr><tr><td>Company → Viewer settings</td><td><strong>Custom List Hint</strong> (the second line in the viewer list)</td><td>Panel</td></tr><tr><td>Company → Viewer settings</td><td><strong>Custom Constructibles Table Column</strong></td><td>Panel</td></tr><tr><td>Machine setup → BTL / BTLx / BVX</td><td><strong>Part data fields</strong> (Designation, Assembly number, Group, Package, Material, Timber grade, Quality grade, Subgroup / Storey)</td><td>Part</td></tr><tr><td>Machine setup → BTL / BTLx / BVX</td><td><strong>User attribute values</strong> (up to 5)</td><td>Part</td></tr></tbody></table><p>The two groups use <strong>two different lists</strong>, because they are resolved against two different things. A viewer header describes a panel; a BTL Designation describes one piece of timber inside that panel. Read the right table below.</p><h2 id="panel-properties" tabindex="-1">Panel properties <a class="header-anchor" href="#panel-properties" aria-label="Permalink to &quot;Panel properties&quot;">​</a></h2><p>Used by the viewer header, the list hint and the custom constructibles column.</p><table><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><code>{design_name}</code></td><td>Design name of the panel</td></tr><tr><td><code>{priority}</code></td><td>Priority inside the batch</td></tr><tr><td><code>{batch_name}</code></td><td>Batch name</td></tr><tr><td><code>{phase_name}</code></td><td>Phase name</td></tr><tr><td><code>{scheduled_prod_date}</code></td><td>Scheduled production date</td></tr><tr><td><code>{client_order_id}</code></td><td>Client order id</td></tr><tr><td><code>{project_name}</code></td><td>Project name</td></tr><tr><td><code>{project_number}</code></td><td>Project number</td></tr><tr><td><code>{super_project}</code></td><td>Super project</td></tr><tr><td><code>{client_name}</code></td><td>Client name</td></tr></tbody></table><p>Plus <strong>your own properties</strong> — see below.</p><h2 id="part-properties" tabindex="-1">Part properties <a class="header-anchor" href="#part-properties" aria-label="Permalink to &quot;Part properties&quot;">​</a></h2><p>Used by the machine file fields (BTL, BTLx and BVX). These are resolved <strong>per part</strong>, so a single file covering a whole batch still carries the right panel name on every piece.</p><table><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><code>{part_pos}</code></td><td>Part reference / position</td></tr><tr><td><code>{name}</code></td><td>Part name</td></tr><tr><td><code>{material}</code></td><td>Material</td></tr><tr><td><code>{description}</code></td><td>Part description</td></tr><tr><td><code>{erp_mat}</code></td><td>ERP material code</td></tr><tr><td><code>{comment}</code></td><td>Comment</td></tr><tr><td><code>{finish}</code></td><td>Finish</td></tr><tr><td><code>{width}</code> / <code>{height}</code> / <code>{length}</code></td><td>Dimensions</td></tr><tr><td><code>{unit}</code></td><td>Unit</td></tr><tr><td><code>{profile_size}</code></td><td>Profile size</td></tr><tr><td><code>{shaped_section_name}</code></td><td>Shaped section name</td></tr><tr><td><code>{zone}</code></td><td>Zone</td></tr><tr><td><code>{assembly_name}</code></td><td>Panel name</td></tr><tr><td><code>{design_name}</code></td><td>Panel name — the same value as <code>{assembly_name}</code></td></tr><tr><td><code>{batch}</code></td><td>Batch name</td></tr><tr><td><code>{phase}</code></td><td>Phase name</td></tr><tr><td><code>{project_name}</code></td><td>Project name</td></tr><tr><td><code>{project_number}</code></td><td>Project number</td></tr><tr><td><code>{super_project_name}</code></td><td>Super project</td></tr><tr><td><code>{client_order_id}</code></td><td>Client order id</td></tr></tbody></table><p>Plus <strong>your own properties</strong> — see below.</p><div class="tip custom-block"><p class="custom-block-title">The panel names also work here</p><p><code>{super_project}</code>, <code>{batch_name}</code> and <code>{phase_name}</code> — the names the panel list above uses — are accepted in machine file fields too, and give the same value as <code>{super_project_name}</code>, <code>{batch}</code> and <code>{phase}</code>. You do not have to remember which list you are in.</p></div><h2 id="your-own-properties" tabindex="-1">Your own properties <a class="header-anchor" href="#your-own-properties" aria-label="Permalink to &quot;Your own properties&quot;">​</a></h2><p>Both lists also accept <strong>any property of your own models</strong>. These are the keys stored on a panel as client metadata: whatever your IFC parsing setup extracts, or whatever your ERP writes through the API. They are different at every company — <code>{montagevolgorde}</code> is a real property at one company and a typo at every other.</p><p>Two ways to see yours:</p><ul><li>The <strong>Insert property</strong> button lists them under <em>Your own properties</em>. It is read from your own panels, so if the section is empty it means none of your panels carry properties of their own — not that the list failed to load.</li><li>On any panel: <strong>Constructibles → open the panel → Client meta</strong>.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>A property that does not exist is not an error.</strong> In the viewer settings it renders as <code>---</code>; in machine files it renders empty. Nothing fails, so a typo is silent — which is exactly why the Insert property button exists.</li><li><strong>Free text is kept as it is.</strong> <code>Order {client_order_id} - {design_name}</code> gives <code>Order ORD-88 - HD-529</code>.</li><li><strong>Every property must be named.</strong> <code>{}</code> and <code>{0}</code> are not accepted, and the field will say so before you can save.</li><li><strong>Every brace must be closed.</strong> <code>{design_name</code> is rejected the same way.</li><li><strong>To print a literal brace</strong>, double it: <code>{{</code> gives <code>{</code>.</li><li><strong>Numbers can be padded</strong>: <code>{priority:03d}</code> gives <code>007</code>. This only works on numeric properties.</li><li><strong>Your own properties cannot override the ones in the tables above.</strong> If one of your model properties is called <code>design_name</code>, <code>{design_name}</code> still means the design name.</li></ul>',25),s=[a];function n(i,c,p,l,h,u){return t(),r("div",null,s)}const y=e(d,[["render",n]]);export{g as __pageData,y as default};
